"""One-time batch04 artifact generation. No network or database writes."""
from pathlib import Path
import csv, hashlib, html, json, re
from school_pipeline.approach_migration import validate_records
BASE=Path('outputs/approach_county_review'); B=BASE/'batch04_10schools_20261027'; S=B/'sources'; DATE='2026-10-27'
def text(name):
 s=(S/(name+'.html')).read_text(errors='replace');s=re.sub(r'<(script|style)\b.*?</\1>','',s,flags=re.S)
 return ' '.join(html.unescape(re.sub('<[^>]+>',' ',s)).split())
def title(name):
 s=(S/(name+'.html')).read_text(errors='replace');return ' '.join(html.unescape(re.search(r'<title[^>]*>(.*?)</title>',s,re.S|re.I)[1]).split())
pre='https://www.sigtuna.se/utbildning-och-barnomsorg/grundskola/grundskolor/ekillaskolan/'
urls={'bredang':'https://grundskola.stockholm/hitta-grundskola/grundskola/bredangsskolan','ekilla':'https://www.sigtuna.se/ekillaskolan','ekilla_on':pre+'pa-ekillaskolan.html','ekilla_methods':pre+'arbetssatt-och-kvalitetsarbete.html','ekilla_welcome':pre+'pa-ekillaskolan/valkommen-till-ekillaskolan.html','ekilla_info':pre+'pa-ekillaskolan/information-om-ekillaskolan.html','visattra':'https://www.huddinge.se/visattraskolan','visattra_about':'https://www.huddinge.se/visattraskolan/om-skolan','kristna':'https://www.kristnaskolan.se/profil/verksamhetside/','kristna_home':'https://www.kristnaskolan.se/','tallkrogen':'https://grundskola.stockholm/hitta-grundskola/grundskola/tallkrogens-skola','evia':'https://wemind.se/hvb/hvb-evia/','evia_school':'https://wemind.se/skola/eviaskolan-haninge/','magelungen':'https://magelungen.com/enheter/sodertalje-grundskola/','alby':'https://www.sundbyberg.se/lillaalbyskola','jarfalla_directory':'https://www.jarfalla.se/forskolaskolaochutbildning/grundskola/hittaochjamforgrundskola.4.792994e6191da7e1ba831faa.html','fjallen':'https://www.jarfalla.se/forskolaskolaochutbildning/grundskola/grundskola/viksjo/fjallenskolan.4.36ac70f31639ecd947f2f49.html','nordic':'https://nordicinternational.se/essingen/','nordic_about':'https://nordicinternational.se/essingen/om-skolan/','nordic_houses':'https://nordicinternational.se/vart-koncept/houses/'}
selection=json.loads((BASE/'next_batch_after_batch03.json').read_text());assert len(selection)==10
ledger=list(csv.DictReader((BASE/'county_progress_20261027_after_batch03.csv').open()));lookup={r['school_id']:r for r in ledger}
assert len(ledger)==len(lookup)==762
assert [r['school_id'] for r in selection]==[r['school_id'] for r in sorted(ledger,key=lambda r:r['school_id']) if r['review_state']=='Not yet contextually reviewed'][:10]
evidence=[];codes=[]
def add(sid,src,quote,note,cat=None,sub='',level='Explicit'):
 assert quote in text(src),(src,quote)
 assert '\ufffd' not in quote
 eid=f'ae_b04_{sid}_{sum(e["school_id"]==sid for e in evidence)+1:02d}'
 evidence.append(dict(evidence_id=eid,school_id=sid,source_url=urls[src],page_title=title(src),accessed_date=DATE,quoted_text=quote,evidence_type='School website self-description',interpretation_note=note))
 if cat:
  codes.append(dict(code_id=f'ac_b04_{sid}_{sum(c["school_id"]==sid for c in codes)+1:02d}',school_id=sid,category=cat,subcategory=sub,coding_level=level,confidence='High' if level=='Explicit' else 'Medium',evidence_id=eid,coder_note='Assistant contextual review; codebook v1; coding date 2026-10-27. '+note+' Self-description, not independently verified practice.',review_status='Reviewed'))
add('14121892','bredang','Vi har ett mångårigt musiksamarbete med kulturskolan El Sistema, där alla barn får lära sig att spela ett instrument.','Ordinary Bredängsskolan F–9 page, stored grades 1–9; preschool class identified separately by website. Sustained music partnership, not ordinary subject list. Page says all children but does not specify delivery years/frequency: do not invent them. Separately linked adapted unit excluded. Malformed robots response retained; no affirmative blanket collection/reuse permission.','Arts and creative learning','El Sistema instrumental-music partnership')
add('14472068','kristna','Skolans kristna profil utgör en central del av vår verksamhet. Det går en rak linje mellan skolans värdegrundsarbete, vår vision och vår kristna profil.','Hammarbyhöjden F–9 school matched to registered school website and homepage locality/year range. Profile page describes Kristendomskunskap in years 1–9 plus Chapel/prayer; this is a neutral account of school wording, not a legal assessment, judgement of implementation or inference about pupil beliefs. Generic creativity and kulturskola offering do not establish integrated arts pedagogy.','Other stated profile','Christian profile')
add('14845171','evia_school','Eviaskolan arbetar med det evidensbaserade arbetssättet skolövergripande positivt beteendestöd (PBS) för att öka ordning och studiero i skolan, såväl som minska problemskapande beteenden och öka de akademiska resultaten hos eleverna.','Exact unit match: fresh official 14845171 address Klockargatan 17 Västerhaninge and grades 6–9 match school page. PBS and resource/individualised teaching directly described. Evidensbaserade and claimed intended results are school wording, not project verification or causal conclusions. Exclude HVB treatment-home page and other Eviaskolan campuses.','Support, inclusion, or wellbeing emphasis','Resource teaching and schoolwide PBS')
add('14872951','magelungen','Elever i resursskolan följer samma läroplan som den ordinarie skolan men i mindre undervisningsgrupper med hög personaltäthet samt i anpassade lärmiljöer.','Unit-specific Södertälje page address Hertig Carls väg 22 matches fresh official ID 14872951, resource-school flag and stored grades 4–9. Website does not state delivery years in this passage; 4–9 comes from official record. High staffing/smaller groups self-reported, not numerical official ratio or class size. Separate social-service treatment-school option not assumed for every pupil.','Support, inclusion, or wellbeing emphasis','Resource teaching in adapted learning environments')
add('15049834','alby','Vi satsar även på ökad rörelse - Puls Sprint Go - under skoldagen eftersom vi värnar om elevernas hälsa för både knopp och kropp.','Lilla Alby F–6 municipal school page, stored grades 1–6; named movement initiative stated under Pedagogik. Context also describes cross-age buddy system and scheduled values lessons. Do not infer activity duration, health effects or universal frequency. Nearby parks and occasional theme weeks insufficient for outdoor/project code.','Support, inclusion, or wellbeing emphasis','Puls Sprint Go movement emphasis')
add('15171331','nordic','Skolan präglas av en internationell miljö där engelska är en naturlig del av möten i vardagen och där respekt, ansvar och samhörighet stärks bland annat genom vårt House-system.','Essingen-specific page explicitly applies House-system to this school, grades 4–9; about page address Segelbåtsvägen 11b. Linked provider Houses page explains mixed-year membership and regular meetings; provider detail is context, not sole unit evidence. Code only concrete community/wellbeing emphasis. International milieu/inspired pedagogy is too broad for a firm language category; page explicitly says teaching in Swedish. No bilingual/international-curriculum claim.','Support, inclusion, or wellbeing emphasis','House-system community and belonging')
add('15171331','nordic_houses','Ett house utgörs av en blandad grupp elever från alla årskurser i skolan och skapar en gemenskap för eleverna under hela deras tid på skolan.','Provider-level contextual explanation of the House-system explicitly named on Essingen page. Supports interpretation of ac_b04_15171331_01, no duplicate code. Do not independently attach provider detail to other unreviewed units.')
add('14440920','visattra_about','Undervisningen präglas av tydlighet, kvalitet och ett språk- och kunskapsutvecklande arbetssätt som hjälper eleverna att utveckla förståelse, nyfikenhet och lust att lära.','Requires review: F–6 school section says language/knowledge-developing approach but lacks concrete methodological detail for a distinctive category. Not language/international profile. Separate municipality-wide statutory/generic sections excluded. No firm code; no inference of absence.')
add('15080815','fjallen','På Fjällenskolan har vi stadieanpassad resursskoleverksamhet för hela åldersspannet F-9.','Requires review: official 15080815 matches Ekollongränd 1 and F–9/grades 1–9 but specialSupportSchool=false. Shared page also labels Järfälla resursskola and integrated groups. Do not generalise resource provision to whole ordinary unit or silently reassign an ID. No firm code until exact subgroup/unit applicability is resolved. Website body ~600 pupils and metadata >700 conflict; do not import counts.')
validate_records(evidence,codes)
for name,rows in [('Approach_evidence.staged.json',evidence),('Approach_codes.staged.json',codes)]: (B/name).write_text(json.dumps(rows,ensure_ascii=False,indent=2))
scopes={
'14121892':(['bredang'],'F–9 ordinary; adapted unit excluded.','Music partnership explicit; precise delivery years/frequency unspecified. Malformed robots response retained.'),
'14261356':(['ekilla','ekilla_on','ekilla_methods','ekilla_welcome','ekilla_info'],'7–9; municipality-wide platform not a unit-specific profile.','Scoped home/welcome/info/methods review found generic aspirations, ordinary staffing/student voice and transition teambuilding, not distinctive sustained approach. No clear approach evidence within scope; not proof of absence.'),
'14440920':(['visattra','visattra_about'],'F–6 website; 1–6 official grade list.','Language/knowledge-development wording broad; no concrete model. Requires review, no firm category.'),
'14472068':(['kristna_home','kristna'],'F–9 Hammarbyhöjden; Christian profile.','Ordinary subjects, creativity slogan, culturschool offering and Chapel performances not by themselves integrated arts pedagogy. No arts code.'),
'14479858':(['tallkrogen'],'F–6; future temporary relocation not different present unit.','Scoped full municipal school page reviewed: ordinary school/fritids cooperation, planned recess and nearby forest insufficient for firm approach. No clear approach evidence within scope; not proof of absence. Malformed robots retained.'),
'14845171':(['evia','evia_school'],'6–9 Klockargatan 17 Västerhaninge matches fresh official ID.','Registered eviagruppen site redirected to WeMind/HVB; HVB page excluded. School navigation leads Haninge exact address/year match. Other campuses excluded.'),
'14872951':(['magelungen'],'4–9 from fresh official unit, same Hertig Carls väg 22 address.','Unit resource teaching explicit; treatment service is separate optional social-service provision, not all pupils. School-specific page selected from provider homepage register.'),
'15049834':(['alby'],'F–6 municipal school; stored grades 1–6.','Named movement initiative and buddy-system context; no outdoor code from parks or project code from occasional themes.'),
'15080815':(['jarfalla_directory','fjallen'],'F–9 ordinary unit; mixed resource-school page scope unresolved.','Fresh official same address, specialSupportSchool=false. Shared page integrated resource groups/Järfälla resursskola not a schoolwide profile; requires review.'),
'15171331':(['nordic','nordic_about','nordic_houses'],'4–9 Essingen; teaching explicitly in Swedish.','House-system concrete community work code; international milieu/inspired pedagogy insufficient for language category. No bilingual teaching inferred. Provider explanation linked by unit page.')}
review=[];logs=[]
permission='Robots fetched before school-page collection; readable rules do not disallow reviewed school paths. Stockholm malformed response uncertainty retained; Magelungen robots HTTP 404 despite readable body. WeMind root checked after redirect discovery and before school collection. Robots is not reuse permission. No bypass, login, personal-data extraction or bulk crawl. Terms not comprehensively audited; minimal attributed quotations used, no blanket permission claimed.'
for r in selection:
 sid=r['school_id'];ss,scope,note=scopes[sid];n=sum(c['school_id']==sid for c in codes);outcome='Reviewed claim' if n else ('Scoped no clear approach evidence' if sid in ['14261356','14479858'] else 'Uncertain evidence; Requires review')
 review.append(dict(school_id=sid,official_directory_name=r['official_directory_name'],outcome=outcome,evidence_rows=sum(e['school_id']==sid for e in evidence),code_rows=n,unit_scope=scope,followup_note=note,reviewer='Assistant contextual review; not independently verified practice',review_date=DATE,load_status='Not loaded'))
 for src in ss:
  logs.append(dict(school_id=sid,registered_url=r['registered_url'],source_url=urls[src],page_title=title(src),accessed_date=DATE,http_status=200,source_file='sources/'+src+'.html',sha256=hashlib.sha256((S/(src+'.html')).read_bytes()).hexdigest(),page_role='Excluded HVB treatment home; discovery only' if src=='evia' else ('Provider framework context only' if src=='nordic_houses' else ('School directory discovery' if src=='jarfalla_directory' else 'Official school/provider contextual source')),selection_rationale='Official directory ID order, school/locality/page scope checked; Swedish and English about/pedagogy/profile/creative/arts/learning/values concepts used in local page review; no search-snippet coding.',outcome=outcome,scope_note=scope+' '+note,permission_assessment=permission))
 lookup[sid].update(review_state='Contextual review recorded; '+outcome,batch_reference=B.name,collection_status='reviewed_claim' if n else ('scoped_no_clear_evidence' if sid in ['14261356','14479858'] else 'requires_review'),note=scope+' '+note+' Persistence tracked in batch_status.json.')
def csvwrite(path,rows):
 with path.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
csvwrite(B/'review_log.csv',review);csvwrite(BASE/'county_progress_20261027_after_batch04.csv',ledger)
(B/'collection_log.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in logs))
(B/'selection.json').write_text(json.dumps(selection,ensure_ascii=False,indent=2))
(B/'source_manifest.json').write_text(json.dumps([dict(file=p.name,bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted(S.iterdir()) if p.is_file()],indent=2))
(B/'validation.json').write_text(json.dumps(dict(status='PASSED_ARTIFACT_VALIDATION',schools=10,evidence_rows=len(evidence),code_rows=len(codes),quote_substrings_checked=True,ledger_unique_ids=len(lookup),next_id_order_checked=True,not_yet_contextually_reviewed=sum(r['review_state']=='Not yet contextually reviewed' for r in ledger)),indent=2))
(B/'batch_status.json').write_text(json.dumps(dict(status='ARTIFACTS_FINALISED_NOT_LOADED',schools=10),indent=2))
(B/'decision_log.md').write_text('# Batch04 decision log\n\nAssistant contextual review, codebook v1, 2026-10-27. Reviewed means claim/scope reviewed, not independently verified practice. No material codebook change.\n\n'+'\n'.join('- '+sid+': '+s[1]+' '+s[2] for sid,s in scopes.items())+'\n\nBorderline consistency: ordinary statutory support and generic safety not coded. Ekillaskolan transition teambuilding and Tallkrogen school/fritids cooperation do not meet threshold alone. Lilla Alby names an active movement initiative, supported by concrete buddy-system context. Nordic code rests on unit-applied named House-system, not broad international promotion. Visättra does not name a controlled alternative pedagogy. Fjällen evidence records subgroup ambiguity, not profile absence.\n\n'+permission+'\n\nTechnical audit: standard-library text parser used after bs4 import unavailable; gzip check failed on malformed Stockholm bytes, no altered response substituted. Source quotations verified as substrings of normalised saved HTML. Fresh official JSONs retain provenance separately and do not replace official database tables. Minimal school descriptions copied; personal contact details not included in evidence/codes. Raw audit files remain local.\n')
(B/'REPORT.md').write_text('# Batch04 contextual review\n\n10 units in official-ID order. 6 reviewed claim outcomes, 2 scoped no-clear-evidence outcomes, 2 uncertain outcomes. '+str(len(evidence))+' evidence notes; '+str(len(codes))+' codes.\n\nSee review_log.csv for all school outcomes, collection_log.jsonl for exact pages and exclusions, decision_log.md for thresholds and permission caveats, and staged evidence/codes for quotes and source links. Database persistence must be confirmed separately in load_validation.json.\n\nUnresolved: Visättraskolan lacks concrete model details; Fjällenskolan resource-group/ordinary-unit scope unclear. Bredäng music year delivery unspecified. Nordic international wording not promoted to language code. Stockholm malformed robots response and Magelungen HTTP-404 robots body retained as uncertainties. No quality rankings, causal claims or county representativeness.\n')
print((B/'validation.json').read_text())
